import{c as r,Q as a,j as n,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"A Subgoal-driven Framework for Improving Long-Horizon LLM Agents","description":"","frontmatter":{"url":"https://arxiv.org/abs/2603.19685","title":"A Subgoal-driven Framework for Improving Long-Horizon LLM Agents","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2603.19685,"authors":["Taiyi Wang","Sian Gooding","Florian Hartmann","Oriana Riva","Edward Grefenstette"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2603.19685v1","pdf_path":"pdfs/2603.19685.pdf","published_date":"2026-03-20T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-03-20-subgoal-driven-long-horizon-llm-agents-2603-19685.md","filePath":"research/papers/2026-03-20-subgoal-driven-long-horizon-llm-agents-2603-19685.md","lastUpdated":1785909234000}'),t={name:"research/papers/2026-03-20-subgoal-driven-long-horizon-llm-agents-2603-19685.md"};function i(s,e,l,g,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="a-subgoal-driven-framework-for-improving-long-horizon-llm-agents" tabindex="-1">A Subgoal-driven Framework for Improving Long-Horizon LLM Agents <a class="header-anchor" href="#a-subgoal-driven-framework-for-improving-long-horizon-llm-agents" aria-label="Permalink to &quot;A Subgoal-driven Framework for Improving Long-Horizon LLM Agents&quot;">​</a></h1><p><strong>Authors</strong>: Taiyi Wang, Sian Gooding, Florian Hartmann, Oriana Riva, Edward Grefenstette <strong>Published</strong>: March 20, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2603.19685" target="_blank" rel="noreferrer">https://arxiv.org/abs/2603.19685</a> · <a href="https://arxiv.org/html/2603.19685v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2603.19685 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2603.19685" target="_blank" rel="noreferrer">research/papers/pdfs/2603.19685.pdf</a> (50 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Large language model (LLM)-based agents have emerged as powerful autonomous controllers for digital environments, including mobile interfaces, operating systems, and web browsers. Web navigation, for example, requires handling dynamic content and long sequences of actions, making it particularly challenging. Existing LLM-based agents struggle with long-horizon planning in two main ways. During online execution, they often lose track as new information arrives, lacking a clear and adaptive path toward the final goal. This issue is further exacerbated during reinforcement learning (RL) fine-tuning, where sparse and delayed rewards make it difficult for agents to identify which actions lead to success, preventing them from maintaining coherent reasoning over extended tasks. To address these challenges, we propose two contributions. First, we introduce an agent framework that leverages proprietary models for online planning through subgoal decomposition. Second, we present MiRA (Milestoning your Reinforcement Learning Enhanced Agent), an RL training framework that uses dense, milestone-based reward signals. The real-time planning mechanism improves proprietary models such as Gemini by approximately a 10% absolute increase in success rate (SR) on the WebArena-Lite benchmark. Meanwhile, applying MiRA to the open Gemma3-12B model increases its success rate from 6.4% to 43.0%. This performance surpasses proprietary systems such as GPT-4-Turbo (17.6%) and GPT-4o (13.9%), as well as the previous open-model state of the art, WebRL (38.4%). Overall, our findings demonstrate that combining explicit inference-time planning with milestone-based rewards significantly improves an agent&#39;s long-horizon capabilities, paving the way for more robust and general-purpose autonomous systems.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出以 <strong>subgoal decomposition（子目標分解）</strong> 為核心的 agent framework，利用 proprietary models 在 online execution 時做即時規劃，維持朝向 final goal 的 adaptive path。</li><li>提出 <strong>MiRA（Milestoning your Reinforcement Learning Enhanced Agent）</strong>：以 dense、milestone-based reward signals 取代 RL fine-tuning 中常見的 sparse/delayed reward，緩解 credit assignment 難題。</li><li>將 inference-time explicit planning 與 milestone-based reward 結合，針對 long-horizon web navigation（dynamic content + 長 action sequence）此一困難場景設計。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>Real-time planning 機制使 proprietary 模型（如 Gemini）在 <strong>WebArena-Lite</strong> 上 success rate（SR）約 <strong>+10% absolute</strong>。</li><li>MiRA 套用於 open 模型 <strong>Gemma3-12B</strong>：SR 從 <strong>6.4% → 43.0%</strong>。</li><li>該結果超越 proprietary 系統 <strong>GPT-4-Turbo（17.6%）</strong>、<strong>GPT-4o（13.9%）</strong>，以及 previous open-model SOTA <strong>WebRL（38.4%）</strong>。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><p>文件未列明確 limitation 章節（僅依 abstract 判讀）。推測弱點：</p><ul><li>評測集中於 <strong>WebArena-Lite</strong> 單一 benchmark，跨 OS / mobile / 真實網站的泛化未在 abstract 證實。</li><li>Online planning 依賴 <strong>proprietary models（Gemini 等）</strong>，有成本、延遲與可重現性疑慮。</li><li>milestone reward 的設計多半需要 <strong>task-specific 標註或啟發式</strong>，abstract 未說明 milestone 如何自動界定，可能限制可擴展性。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>子目標分解 ↔ The Loop IDENTIFY</strong>：本文 subgoal decomposition 與 core.md 中「實作前先寫可機械驗證的成功條件、把 long task 拆為可獨立 loop 的子條件」高度同構；milestone reward 可視為「強成功條件」的 RL 化身。</li><li><strong>long-horizon agent ↔ <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md） fan-out / handoff</strong>：milestone-based 中間訊號對應 workspace 的 <code>[Checkpoint]</code> 與 handoff 機制——皆為對抗 long-horizon 中 goal drift 與 context rot 的中間錨點。⚠️ 落地門檻：本文為 RL training-time 方法，workspace 為 prompt-time 紀律，無法直接移植訓練流程。</li><li><strong>dense reward ↔ unverified_success 閘門</strong>：milestone reward「逐步驗證而非僅看終點」呼應 core.md TEST「靜態檢查 ≠ 端到端」與確定性 gate 親驗；可作為「為何中間驗證優於 sparse 終點評估」的外部佐證。</li><li>⚠️ 本論文無對應 codebase 落地路徑，僅為概念層參考，勿據此新增框架檔案。</li></ul>',17)])])}const h=r(t,[["render",i]]);export{p as __pageData,h as default};
